<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { aiApi, ApiError } from '../services/aiApi'
import { downloadCase, type CasePhoto } from './caseModel'
import { preparePhoto } from './photoSimulation'
import DentalCareOptions from './DentalCareOptions.vue'
import ScreeningPerformance from './ScreeningPerformance.vue'
import { allFdi, annotationIssues, assessmentStates, blankLocation, conditions, describeLocation, newScreeningPhoto, newScreeningRecord, parseScreeningRecord, relationshipKeys, researchReadiness, screeningReport, screeningTaxonomy, standardViews, stateNames, viewNames, type Finding, type ScreeningRecord } from './screeningModel'
import './screening.css'
import './photoSimulator.css'
const props=defineProps<{photos:CasePhoto[];subject:string;photoBusy:boolean;user:{id:number;email:string}|null;authPending:boolean;authError:string}>()
const emit=defineEmits<{addPhotos:[event:Event];authenticate:[email:string,password:string,register:boolean];openSimulator:[sourceHash:string]}>()
const record=reactive<ScreeningRecord>(newScreeningRecord(props.subject)),mode=ref<'annotation'|'demonstration'|'performance'>('annotation')
const selected=ref(conditions[0]!.id),query=ref(''),category=ref('all'),filterState=ref('all'),includeImages=ref(false),pending=ref(false),error=ref(''),message=ref('')
const email=ref(''),password=ref(''),register=ref(false),loadingRecord=ref(false),saved=ref<{id:string;subject_code:string;visit_code:string;partition:string}[]>([])
let generation=0;const controllers=new Set<AbortController>(),excluded=new Set<string>()
const active=computed(()=>conditions.find(item=>item.id===selected.value)!),finding=computed(()=>record.findings.find(item=>item.id===selected.value)!)
const shown=computed(()=>conditions.filter(item=>(category.value==='all'||item.category===category.value)&&(filterState.value==='all'||record.findings.find(f=>f.id===item.id)?.state===filterState.value)&&`${item.name} ${item.user_definition}`.toLowerCase().includes(query.value.toLowerCase().trim())))
const report=computed(()=>screeningReport(record)),issues=computed(()=>annotationIssues(record)),researchIssues=computed(()=>researchReadiness(record,false))
const canReview=computed(()=>record.review.reviewer_role==='orthodontist'&&/^[A-Za-z0-9_-]{1,48}$/.test(record.review.reviewer_code))
const counts=computed(()=>Object.fromEntries(assessmentStates.map(state=>[state,record.findings.filter(f=>f.state===state).length])))
const simulatorSource=computed(()=>record.photos.find(photo=>props.photos.some(source=>source.sha256===photo.source_sha256))?.source_sha256)
const relatedNames=computed(()=>[...active.value.broader_ids,...active.value.related_ids].map(id=>conditions.find(item=>item.id===id)?.name).join(', '))
const missingViewNames=computed(()=>report.value.missing.map(view=>viewNames[view]).join(', '))
const relationNames:Record<string,string>={molar_right:'Right molar relationship',molar_left:'Left molar relationship',canine_right:'Right canine relationship',canine_left:'Left canine relationship',incisor:'Incisor relationship'}
const classNames:Record<string,string>={not_recorded:'Not recorded',uncertain:'Uncertain',not_assessable:'Not assessable',class_i:'Class I',class_ii:'Class II',class_ii_division_1:'Class II division 1',class_ii_division_2:'Class II division 2',class_iii:'Class III'}
const qualityReasons=['blur','lighting','occlusion','cropped_teeth','unconfirmed_view','not_biting_together','non_dental_image','radiograph_or_scan','other']
function invalidateReview(){if(!loadingRecord.value){record.review.annotations_reviewed=false;record.consent_storage=false;record.consent_training=false;message.value=''}}
watch(()=>JSON.stringify({subject:record.subject_code,visit:record.visit_code,partition:record.partition,age:record.age_years,dentition:record.dentition_stage,scope:record.scope,normal:record.normal_appearance,braces:record.existing_braces,photos:record.photos,findings:record.findings,classifications:record.classifications}),invalidateReview)
watch(()=>[record.review.reviewer_code,record.review.reviewer_role],()=>{if(!loadingRecord.value){record.review.annotations_reviewed=false;record.review.definitions_reviewed=false;record.consent_training=false;record.consent_storage=false}})
watch(includeImages,()=>{if(!loadingRecord.value){record.consent_storage=false;record.consent_training=false}})
watch(()=>[record.data_rights,record.rights_reference],()=>{if(!loadingRecord.value){record.consent_storage=false;record.consent_training=false}})
watch(()=>props.photos.map(photo=>photo.sha256).join('|'),(current,previous)=>{const hashes=new Set(current.split('|'));for(const hash of (previous||'').split('|').filter(Boolean))if(!hashes.has(hash)){removePhoto(hash);excluded.delete(hash)};for(const photo of props.photos)if(!excluded.has(photo.sha256)&&!record.photos.some(item=>item.source_sha256===photo.sha256)&&record.photos.length<6)record.photos.push(newScreeningPhoto(photo))},{immediate:true})
watch(()=>props.user?.id,()=>{generation++;for(const controller of controllers)controller.abort();controllers.clear();pending.value=false;saved.value=[];record.consent_storage=false;record.consent_training=false;error.value='';message.value='';if(props.user)void refreshSaved()},{immediate:true})
onBeforeUnmount(()=>{generation++;for(const controller of controllers)controller.abort()})
function photoUrl(hash:string){return props.photos.find(photo=>photo.sha256===hash)?.url||record.photos.find(photo=>photo.source_sha256===hash)?.data_url||undefined}
function viewStatus(view:string){const matches=record.photos.filter(photo=>photo.standard_view===view);return matches.length?matches.map(photo=>photo.view_confirmed?photo.quality.replaceAll('_',' '):'view unconfirmed').join(', '):'not supplied'}
function removePhoto(hash:string){excluded.add(hash);record.photos=record.photos.filter(photo=>photo.source_sha256!==hash);for(const item of record.findings)item.photo_ids=item.photo_ids.filter(id=>id!==hash)}
function toothIds(index:number,value:string){finding.value.locations[index]!.tooth_ids=value.trim()?value.split(/[\s,]+/).filter(Boolean).map(Number):[]}
function findingLocation(item:Finding){return item.locations.length?item.locations.map(describeLocation).join('; '):'not established'}
function fail(failure:unknown){error.value=failure instanceof ApiError&&failure.status===0?'The local screening store is unavailable. The draft remains on this screen.':failure instanceof Error?failure.message:'The screening action could not be completed.'}
async function prepareRecord(withImages:boolean){
 if(record.age_years!==null&&(!Number.isFinite(record.age_years)||record.age_years<0||record.age_years>120))throw new Error('Enter a recorded age from 0 to 120, or leave it unknown.')
 if(record.findings.some(item=>item.locations.some(location=>location.tooth_ids.some(id=>!allFdi.includes(id))||new Set(location.tooth_ids).size!==location.tooth_ids.length)))throw new Error('Use distinct valid permanent or primary FDI identifiers, or leave tooth identity unassigned.')
 if(record.data_rights==='appropriately_licensed'&&!record.rights_reference.trim())throw new Error('Record the appropriate data licence reference before exporting or saving this record.')
 const value=JSON.parse(JSON.stringify(record)) as ScreeningRecord
 if(!/^[A-Za-z0-9_-]{1,48}$/.test(value.subject_code)||!/^[A-Za-z0-9_-]{1,48}$/.test(value.visit_code))throw new Error('Enter coded subject and visit IDs using 1–48 letters, numbers, underscores or hyphens.')
 if(value.age_years!==null&&(!Number.isFinite(value.age_years)||value.age_years<0||value.age_years>120))throw new Error('Enter a recorded age from 0 to 120, or leave it unknown.')
 for(const photo of value.photos){
  if(!withImages){photo.data_url=null;photo.input_sha256=null;continue}
  if(photo.data_url&&photo.input_sha256)continue
  const url=photoUrl(photo.source_sha256);if(!url)throw new Error('Reattach the source photograph before including its pixels in a research bundle.')
  const prepared=await preparePhoto(url);photo.data_url=prepared.data_url;photo.input_sha256=prepared.input_sha256
 }
 return value
}
async function exportRecord(research=false){
 if(pending.value||mode.value!=='annotation')return
 const version=generation;pending.value=true;error.value='';message.value=''
 try{const value=await prepareRecord(research);if(version!==generation)return;if(research){if(!record.consent_training)throw new Error('Research permission changed while the bundle was being prepared.');const missing=researchReadiness(value);if(missing.length)throw new Error(missing[0])};downloadCase(value,research?'orthodontic-reviewed-photo-bundle.json':'orthodontic-screening-annotations.json');message.value=research?'Reviewed research bundle exported. It contains permitted photograph pixels and self-attested labels; no classifier was trained.':'Annotation draft exported without image pixels. No automatic screening or training occurred.'}
 catch(failure){if(version===generation)fail(failure)}finally{if(version===generation)pending.value=false}
}
async function refreshSaved(){
 if(!props.user)return;const version=generation,controller=new AbortController();controllers.add(controller)
 try{const result=await aiApi.get<{cases:typeof saved.value}>('/dental/screening/cases',controller.signal);if(version===generation)saved.value=result.cases}
 catch(failure){if(version===generation&&!controller.signal.aborted)fail(failure)}finally{controllers.delete(controller)}
}
async function saveRecord(){
 if(!props.user||!record.consent_storage||record.data_rights==='not_confirmed'||pending.value||mode.value!=='annotation')return
 const version=generation,controller=new AbortController();controllers.add(controller);pending.value=true;error.value='';message.value=''
 try{const value=await prepareRecord(includeImages.value);if(version!==generation||!record.consent_storage)return;await aiApi.csrf();if(version!==generation||!record.consent_storage)return;const result=await aiApi.post<{cases:typeof saved.value}>('/dental/screening/cases',value,controller.signal,70000);if(version!==generation)return;saved.value=result.cases;record.consent_storage=false;message.value='Screening annotations saved in this account’s local store. They are separate from tooth-outline training.'}
 catch(failure){if(version===generation&&!controller.signal.aborted)fail(failure)}finally{controllers.delete(controller);if(version===generation)pending.value=false}
}
async function loadRecord(id:string){
 if(pending.value||!props.user)return;const version=++generation,controller=new AbortController();controllers.add(controller);pending.value=true;error.value=''
 try{const result=await aiApi.get<unknown>('/dental/screening/cases/'+id,controller.signal);if(version!==generation)return;const value=parseScreeningRecord(result);loadingRecord.value=true;Object.assign(record,value);includeImages.value=value.photos.some(photo=>!!photo.data_url);record.consent_storage=false;record.consent_training=false;mode.value='annotation';selected.value=conditions[0]!.id;await nextTick();message.value='Saved visit loaded. Review changes before recording a new specialist attestation.'}
 catch(failure){if(version===generation&&!controller.signal.aborted)fail(failure)}finally{controllers.delete(controller);loadingRecord.value=false;if(version===generation)pending.value=false}
}
async function deleteRecord(id:string){
 if(pending.value||!props.user)return;const version=generation;pending.value=true;error.value=''
 try{await aiApi.csrf();if(version!==generation)return;await aiApi.delete('/dental/screening/cases/'+id);if(version!==generation)return;await refreshSaved();message.value='Saved screening visit removed. Your current unsaved draft remains on screen.'}
 catch(failure){if(version===generation)fail(failure)}finally{if(version===generation)pending.value=false}
}
const demoChoice=ref('crowding_rotation')
const demonstrations:Record<string,{title:string;findings:string[];explanation:string}>={crowding_rotation:{title:'Possible crowding detected.',findings:['dental_crowding','rotated_teeth'],explanation:'Synthetic example: overlapping or turned crowns can be recorded together. This result was written as an example, not detected in your photograph.'},spacing:{title:'Possible spacing detected.',findings:['generalized_spacing','midline_diastema'],explanation:'Synthetic example: several gaps and a central gap can coexist. The child label does not automatically set the broader label.'},open_bite:{title:'Possible anterior open bite detected.',findings:['anterior_open_bite'],explanation:'Synthetic example with a declared closed-bite record. Actual contact, cause and treatment need require clinical assessment.'},normal:{title:'No obvious abnormality in the supplied views.',findings:[],explanation:'Synthetic normal-appearance example. This wording never confirms that treatment is unnecessary or that hidden conditions are absent.'},insufficient:{title:'The supplied image is insufficient.',findings:[],explanation:'Synthetic quality-failure example: return no photographic findings and request appropriate standardized views.'},out_of_scope:{title:'The supplied input is outside this photo workflow.',findings:[],explanation:'Synthetic scope example: a scan, radiograph or non-dental image must not become a photographic tooth-alignment result.'}}
const demo=computed(()=>demonstrations[demoChoice.value]!)
</script>
<template>
 <section class="screening-studio" data-testid="orthodontic-screening" aria-label="Orthodontic screening annotations">
  <header class="screening-heading panel"><span class="dental-eyebrow">ORTHODONTIC SCREENING / LOCAL RESEARCH</span><h2>Record what is visible.<br/>Keep what is unknown.</h2><p>41 starting conditions, separate dental classifications and a structured review trail.</p><div class="screening-badges"><span>No condition classifier available</span><span>Definitions awaiting orthodontist review</span></div><p class="screening-mode-note">The current tools support annotation and a labelled demonstration. Photos are not automatically classified for bite or alignment abnormalities. The local tooth-outline model remains a separate tool.</p></header>
  <div class="screening-mode-switch" role="group" aria-label="Screening mode"><button :aria-pressed="mode==='annotation'" @click="mode='annotation'">Annotate a visit</button><button :aria-pressed="mode==='demonstration'" @click="mode='demonstration'">Demonstration only</button><button :aria-pressed="mode==='performance'" @click="mode='performance'">Per-condition performance</button></div>
  <div v-show="mode==='annotation'">
   <section class="screening-record panel"><h3>Patient & visit record</h3><div class="screening-fields"><label>Coded subject<input v-model="record.subject_code" maxlength="48" aria-label="Screening subject code"/></label><label>Coded visit<input v-model="record.visit_code" maxlength="48" aria-label="Screening visit code"/></label><label>Patient partition<select v-model="record.partition" aria-label="Screening patient partition"><option value="train">Training</option><option value="validation">Validation</option><option value="test">Test · held out</option></select></label><label>Recorded age in years<input :value="record.age_years??''" type="number" min="0" max="120" step=".1" placeholder="Unknown" aria-label="Recorded screening age" @input="record.age_years=($event.target as HTMLInputElement).value.trim()===''?null:Number(($event.target as HTMLInputElement).value)"/></label><label>Dentition stage<select v-model="record.dentition_stage" aria-label="Screening dentition stage"><option value="unknown">Unknown</option><option value="primary">Primary</option><option value="mixed">Mixed</option><option value="permanent">Permanent</option></select></label><label>Image-set scope<select v-model="record.scope" aria-label="Screening image-set scope"><option value="not_reviewed">Not reviewed</option><option value="in_scope">In-scope dental photographs</option><option value="insufficient_images">Insufficient images</option><option value="out_of_scope">Out of scope</option></select></label><label>Reviewer’s overall normal appearance<select v-model="record.normal_appearance" aria-label="Screening normal appearance"><option v-for="state in assessmentStates" :key="state" :value="state">{{stateNames[state]}}</option></select></label><label>Existing braces<select v-model="record.existing_braces" aria-label="Screening existing braces"><option v-for="state in assessmentStates" :key="state" :value="state">{{stateNames[state]}}</option></select></label></div><p>Use the same coded patient and partition for all photographs and visits. Age, dentition and normal appearance are entered by a reviewer, never inferred from the picture.</p></section>
   <section class="screening-photos panel"><div class="screening-section-top"><h3>1. Image quality & available views</h3><label class="button-secondary dental-file-button">Add screening photos<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="photoBusy||record.photos.length>=6" aria-label="Add screening photographs" @change="emit('addPhotos',$event)"/></label></div><p>Use standardized frontal-bite, right-bite, left-bite, upper-occlusal and lower-occlusal photos. Confirm each view and whether the teeth are biting together. Screen-side position is not the patient’s left or right.</p><div class="screening-view-coverage"><span v-for="view in standardViews.slice(0,5)" :key="view" :class="{available:report.usable.some(photo=>photo.standard_view===view)}">{{viewNames[view]}} · {{viewStatus(view)}}</span></div>
    <p v-if="!record.photos.length" class="screening-empty">Add photographs to record visible findings. No image has been analyzed.</p><div class="screening-photo-grid"><article v-for="(photo,index) in record.photos" :key="photo.source_sha256"><img v-if="photoUrl(photo.source_sha256)" :src="photoUrl(photo.source_sha256)" :alt="`Screening source photo ${index+1}; view unverified until confirmed`"/><div v-else class="screening-empty">Image pixels are not stored. Reattach the original photograph to inspect it.</div><div class="screening-fields"><label>Standardized view<select v-model="photo.standard_view" :aria-label="`Screening photo ${index+1} view`"><option v-for="view in standardViews" :key="view" :value="view">{{viewNames[view]}}</option></select></label><label>Image quality<select v-model="photo.quality" :aria-label="`Screening photo ${index+1} quality`"><option value="not_reviewed">Not reviewed</option><option value="usable">Usable</option><option value="limited">Limited</option><option value="insufficient">Insufficient</option><option value="out_of_scope">Out of scope</option></select></label><label>Teeth biting together<select v-model="photo.biting_together" :aria-label="`Screening photo ${index+1} biting together`"><option value="unknown">Unknown</option><option value="yes">Yes · reviewer recorded</option><option value="no">No</option></select></label></div><label class="dental-check"><input v-model="photo.view_confirmed" type="checkbox" :aria-label="`Confirm screening photo ${index+1} view`"/>I checked the view against this photograph.</label><label class="dental-check"><input v-model="photo.patient_orientation_confirmed" type="checkbox"/>I checked the patient’s side/orientation, including any mirroring.</label><details><summary>Quality limitations</summary><label v-for="reason in qualityReasons" :key="reason" class="dental-check"><input v-model="photo.quality_reasons" :value="reason" type="checkbox"/>{{reason.replaceAll('_',' ')}}</label></details><button class="dental-text-button" @click="removePhoto(photo.source_sha256)">Remove from screening</button></article></div>
   </section>
   <section class="screening-labels panel"><div class="screening-section-top"><div><h3>2. Multi-label observations</h3><p>Choose each state explicitly. Unreviewed labels start as not assessable. Several findings can coexist.</p></div><div class="screening-state-counts"><span v-for="state in assessmentStates" :key="state">{{counts[state]}} {{stateNames[state].toLowerCase()}}</span></div></div><div class="screening-label-layout"><aside><label>Find a condition<input v-model="query" type="search" placeholder="Crowding, overjet, eruption…" aria-label="Find screening condition"/></label><label>Category<select v-model="category" aria-label="Screening condition category"><option value="all">All 41 conditions</option><option v-for="item in screeningTaxonomy.categories" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Assessment state<select v-model="filterState" aria-label="Filter screening assessment state"><option value="all">All states</option><option v-for="state in assessmentStates" :key="state" :value="state">{{stateNames[state]}}</option></select></label><div class="screening-label-list" aria-label="Screening condition taxonomy"><button v-for="item in shown" :key="item.id" :aria-pressed="selected===item.id" @click="selected=item.id"><span>{{item.name}}</span><small>{{stateNames[record.findings.find(f=>f.id===item.id)!.state]}}</small></button><p v-if="!shown.length">No matching conditions.</p></div></aside>
     <article class="screening-condition-editor" :aria-label="`Annotate ${active.name}`"><span class="dental-eyebrow">{{active.evidence_scope.replaceAll('_',' ')}}</span><h4>{{active.name}}</h4><p>{{active.simple_explanation}}</p><details><summary>Definition & limits · draft content</summary><p>{{active.user_definition}}</p><ul><li v-for="limit in active.limitations" :key="limit">{{limit}}</li></ul></details><p v-if="active.id==='increased_overjet'||active.id==='deep_overbite'" class="screening-important">Overjet is horizontal overlap. Overbite is vertical overlap. Small amounts of each can be normal; no distance or severity is measured here.</p><fieldset class="screening-four-states"><legend>Assessment for {{active.name}}</legend><label v-for="state in assessmentStates" :key="state"><input v-model="finding.state" type="radio" :name="`state-${active.id}`" :value="state"/>{{stateNames[state]}}</label></fieldset><label>Evidence basis<select v-model="finding.evidence_basis" aria-label="Screening finding evidence basis"><option value="not_recorded">Not recorded</option><option value="photo_observation">Photographic observation · reviewer entered</option><option value="clinical_record_review">Clinical record review · reviewer entered</option><option value="history_report">Reported history</option></select></label><fieldset v-if="finding.evidence_basis==='photo_observation'" class="screening-evidence"><legend>Supporting photographs</legend><label v-for="(photo,index) in record.photos" :key="photo.source_sha256" class="dental-check"><input v-model="finding.photo_ids" type="checkbox" :value="photo.source_sha256"/>Photo {{index+1}} · {{viewNames[photo.standard_view]}} · {{photo.quality.replaceAll('_',' ')}}</label><p v-if="!record.photos.length">No photographs supplied.</p></fieldset><label v-if="['clinical_record_review','history_report'].includes(finding.evidence_basis)">Coded record / history reference<input v-model="finding.record_reference" maxlength="300" placeholder="e.g. EXAM_01 or HISTORY_02; avoid patient names" aria-label="Screening record reference"/></label><label>Observation or reason for uncertainty<textarea v-model="finding.note" maxlength="1000" rows="3" aria-label="Screening finding note"/></label>
      <div class="screening-locations"><div class="screening-section-top"><h5>Affected locations · entered manually</h5><button class="dental-text-button" :disabled="finding.locations.length>=8" @click="finding.locations.push(blankLocation())">Add affected location</button></div><p v-if="!finding.locations.length">Location not established.</p><div v-for="(location,index) in finding.locations" :key="index" class="screening-location"><div class="screening-fields"><label>Arch<select v-model="location.arch" :aria-label="`Affected arch ${index+1}`"><option value="unknown">Unknown</option><option value="upper">Upper</option><option value="lower">Lower</option><option value="both">Both</option></select></label><label>Region<select v-model="location.region"><option value="unknown">Unknown</option><option value="anterior">Anterior</option><option value="posterior">Posterior</option><option value="whole_arch">Whole arch</option><option value="tooth_specific">Tooth specific</option></select></label><label>Patient side<select v-model="location.side" :aria-label="`Affected patient side ${index+1}`"><option value="unknown">Unknown</option><option value="patient_left">Patient’s left</option><option value="patient_right">Patient’s right</option><option value="bilateral">Bilateral</option><option value="midline">Midline</option></select></label><label>FDI teeth · optional<input :value="location.tooth_ids.join(', ')" placeholder="e.g. 11, 21" :aria-label="`Screening FDI teeth ${index+1}`" @change="toothIds(index,($event.target as HTMLInputElement).value)"/></label></div><label class="dental-check"><input v-model="location.tooth_identity_confirmed" type="checkbox"/>These tooth identifiers were reliably established manually.</label><button class="dental-text-button" @click="finding.locations.splice(index,1)">Remove location</button></div></div>
      <p v-if="active.broader_ids.length||active.related_ids.length" class="screening-relation-note">Related concepts: {{relatedNames}}. Relationships never automatically set another label.</p><div class="screening-sources"><a v-for="source in screeningTaxonomy.sources.filter(source=>active.source_ids.includes(source.id))" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.publisher}} · {{source.title}} ↗</a></div>
     </article></div></section>
   <section class="screening-record panel"><h3>3. Clinician-entered dental classifications</h3><p>Record molar, canine and incisor relationships separately where appropriate. A dental classification does not establish the underlying skeletal relationship. Class II divisions are recorded for the overall/incisor classification.</p><label class="dental-check"><input v-model="record.classifications.entered_by_clinician" type="checkbox"/>These relationships were entered by a clinician.</label><div class="screening-fields"><label>Overall dental classification<select v-model="record.classifications.overall" aria-label="Overall dental classification"><option v-for="value in ['not_recorded','uncertain','not_assessable','class_i','class_ii_division_1','class_ii_division_2','class_iii']" :key="value" :value="value">{{classNames[value]}}</option></select></label><label v-for="key in relationshipKeys" :key="key">{{relationNames[key]}}<select v-model="record.classifications[key]" :aria-label="relationNames[key]"><option v-for="value in key==='incisor'?['not_recorded','uncertain','not_assessable','class_i','class_ii_division_1','class_ii_division_2','class_iii']:['not_recorded','uncertain','not_assessable','class_i','class_ii','class_iii']" :key="value" :value="value">{{classNames[value]}}</option></select></label></div><label>Classification record notes<textarea v-model="record.classifications.note" maxlength="1000" rows="2"/></label></section>
   <section class="screening-results panel" aria-label="Reviewer screening summary"><span class="dental-eyebrow">REVIEWER-ENTERED SUMMARY · NO AUTOMATIC CLASSIFIER</span><h3>4. Possible findings & what remains unknown</h3><p>Usable, confirmed photographs: {{report.usable.length}} / {{record.photos.length}}. {{report.notAssessable}} of 41 condition labels remain not assessable.</p><p v-if="report.normal" class="screening-normal">Reviewer recorded: “No obvious abnormality in the supplied views.” This does not confirm that treatment is unnecessary or exclude conditions outside these views.</p><p v-if="!report.possible.length&&!report.uncertain.length&&!report.normal">No supported possible findings have been recorded. This is not a negative screen or a normal diagnosis.</p><article v-for="item in report.possible" :key="item.condition.id" class="screening-result-card"><span>{{item.basis}}</span><h4>Possible {{item.condition.name.toLowerCase()}}</h4><p>{{item.condition.simple_explanation}}</p><p>Location: {{findingLocation(item.finding)}}.</p><p v-if="item.finding.note">Reviewer note: {{item.finding.note}}</p><small>{{item.condition.limitations.join(' ')}}</small></article><article v-for="item in report.uncertain" :key="item.condition.id" class="screening-result-card"><h4>Uncertain: {{item.condition.name}}</h4><p>{{item.condition.simple_explanation}}</p><small>{{item.basis}}. Additional evidence is needed.</small></article><details v-if="report.withheld.length"><summary>Findings not established by the supplied evidence ({{report.withheld.length}})</summary><article v-for="item in report.withheld" :key="item.condition.id"><strong>{{item.condition.name}}</strong><ul><li v-for="reason in item.reasons" :key="reason">{{reason}}</li></ul></article></details><div class="screening-limitations"><h4>What cannot be assessed here</h4><p>Photos alone do not establish root positions, skeletal relationships, impaction, congenital tooth absence, safe movements, severity or treatment need. A missing tooth in a picture does not establish hypodontia, impaction or delayed eruption. There are no invented measurements or confidence percentages.</p><p v-if="report.missing.length">View gaps (missing, unusable or unconfirmed): {{missingViewNames}}.</p><p>{{report.reviewRecommended?'An orthodontic review is appropriate to check these observations and any missing information.':'An orthodontist must still assess treatment need using the individual clinical record.'}} Further examination or imaging should be chosen by the treating clinician when indicated.</p></div><details v-if="issues.length"><summary>Annotation issues to resolve before reviewed research use ({{issues.length}})</summary><ul><li v-for="issue in issues" :key="issue">{{issue}}</li></ul></details></section>
   <section class="screening-review panel"><h3>5. Review, permissions & local records</h3><p>Definitions remain draft content awaiting professional review. Review checkboxes below record self-attestation; the app does not verify professional credentials or certify clinical validity.</p><div class="screening-fields"><label>Reviewer code<input v-model="record.review.reviewer_code" maxlength="48" aria-label="Screening reviewer code"/></label><label>Reviewer role<select v-model="record.review.reviewer_role" aria-label="Screening reviewer role"><option value="unknown">Unknown</option><option value="student">Dental student</option><option value="patient">Patient</option><option value="dentist">Dentist</option><option value="orthodontist">Orthodontist · self-reported</option></select></label><label>Data rights<select v-model="record.data_rights" aria-label="Screening data rights"><option value="not_confirmed">Not confirmed</option><option value="consented_clinical_data">Consented clinical data</option><option value="appropriately_licensed">Appropriately licensed data</option></select></label><label>Consent / licence reference<input v-model="record.rights_reference" maxlength="300" aria-label="Screening rights reference" placeholder="Coded reference; no names"/></label></div><label class="dental-check"><input v-model="record.review.definitions_reviewed" type="checkbox" :disabled="!canReview"/>As the named orthodontist, I reviewed this taxonomy version’s definitions. This is self-attested.</label><label class="dental-check"><input v-model="record.review.annotations_reviewed" type="checkbox" :disabled="!canReview||!!issues.length"/>As the named orthodontist, I reviewed this visit’s annotations. This is self-attested.</label><label class="dental-check"><input v-model="includeImages" type="checkbox" :disabled="record.data_rights==='not_confirmed'"/>Include permitted re-encoded photo pixels in the local save or research bundle.</label><label class="dental-check"><input v-model="record.consent_training" type="checkbox" :disabled="record.data_rights==='not_confirmed'"/>I have permission to use these photos and annotations for local model research. This does not train a classifier.</label><label class="dental-check"><input v-model="record.consent_storage" type="checkbox" :disabled="record.data_rights==='not_confirmed'"/>I have permission to save this screening record{{includeImages?' and its photo pixels':''}} in this account’s private local store.</label><div v-if="!user" class="screening-auth"><h4>Sign in to save locally</h4><form @submit.prevent="emit('authenticate',email,password,register)"><label>Email<input v-model="email" type="email" required autocomplete="username"/></label><label>Password<input v-model="password" type="password" required minlength="12" :autocomplete="register?'new-password':'current-password'"/></label><label class="dental-check"><input v-model="register" type="checkbox"/>Create a test account</label><button class="button-secondary" :disabled="authPending">{{authPending?'Please wait…':register?'Create account':'Sign in'}}</button><p v-if="authError" role="alert">{{authError}}</p></form></div><div class="screening-actions"><button class="button-secondary" :disabled="pending" @click="exportRecord(false)">Export annotations · no images</button><button class="button-secondary" :disabled="pending||!includeImages||!!researchIssues.length" @click="exportRecord(true)">Export reviewed research photo bundle</button><button class="button-primary" :disabled="pending||!user||!record.consent_storage||record.data_rights==='not_confirmed'" @click="saveRecord">{{pending?'Preparing local record…':'Save screening visit locally'}}</button><button v-if="simulatorSource" class="dental-text-button" @click="emit('openSimulator',simulatorSource)">Open photo simulator</button></div><details><summary>Research-readiness checks</summary><ul v-if="researchIssues.length"><li v-for="issue in researchIssues" :key="issue">{{issue}}</li></ul><p v-else>Review and rights fields are recorded. Image bytes are checked while preparing the explicit research bundle. This is not clinical validation.</p></details><details v-if="user" class="screening-saved"><summary>Saved screening visits ({{saved.length}})</summary><button class="dental-text-button" :disabled="pending" @click="refreshSaved">Refresh saved visits</button><article v-for="item in saved" :key="item.id"><span>{{item.subject_code}} · {{item.visit_code}} · {{item.partition}}</span><button class="button-secondary" :disabled="pending" @click="loadRecord(item.id)">Load visit</button><button class="dental-text-button" :disabled="pending" @click="deleteRecord(item.id)">Delete saved visit</button></article></details><small>All local storage is explicit. Normal upload and tab changes do not save anything. This screening dataset is separate from crown-outline training. Exported research bundles contain patient pixels when explicitly selected.</small></section>
   <DentalCareOptions :case-ids="[]"/>
  </div>
  <section v-if="mode==='demonstration'" class="screening-demo panel" data-testid="screening-demonstration"><span class="dental-eyebrow">SYNTHETIC DEMONSTRATION · NOT PATIENT ANALYSIS</span><h3>See the result wording.</h3><p>This prewritten example does not inspect uploaded photos, run a classifier or create clinical training labels.</p><label>Demonstration scenario<select v-model="demoChoice" aria-label="Screening demonstration scenario"><option value="crowding_rotation">Crowding and rotation</option><option value="spacing">Spacing and central gap</option><option value="open_bite">Anterior open bite</option><option value="normal">No obvious abnormality wording</option><option value="insufficient">Insufficient image</option><option value="out_of_scope">Out-of-scope input</option></select></label><article><span>DEMONSTRATION ONLY</span><h4>{{demo.title}}</h4><p>{{demo.explanation}}</p><p v-for="id in demo.findings" :key="id">{{conditions.find(item=>item.id===id)?.simple_explanation}}</p></article></section>
  <ScreeningPerformance v-if="mode==='performance'"/>
  <p v-if="error" class="dental-error" role="alert">{{error}}</p><p v-if="message" class="screening-message" role="status">{{message}}</p>
 </section>
</template>
